<div style="max-width:960px;margin:0 auto"><h1>Quiz Result</h1><p><?=e($result['module_name'])?> · <?= (int)$result['total_questions']?> question(s)</p>
<div class="card"><h2>Summary</h2><ul><li>Total questions: <?= (int)$result['total_questions']?></li><li>Auto-graded: <?= (int)$result['auto_graded']?></li><li>Correct: <?= (int)$result['correct']?></li><li>Incorrect: <?= (int)$result['incorrect']?></li><li>Unanswered: <?= (int)$result['unanswered']?></li><li>Self-graded: <?= (int)$result['self_graded']?></li><li>Objective score: <?= $result['score']===null?'Not applicable':e((string)$result['score']).'%'?></li></ul><p>Objective score includes MCQ and Match questions only. Self-graded questions are not counted as incorrect.</p></div>
<?php foreach($result['questions'] as $i=>$q):$data=$q['answer_data_decoded'];$student=$q['student_answer']??'';?><div class="card"><span class="badge"><?=strtoupper(e($q['type']))?></span><h3>Question <?= $i+1?></h3><p style="white-space:pre-wrap"><?=e($q['question_text'])?></p>
<?php if($q['type']==='mcq'):?><p>Your answer: <?=e($student!==''?$student:'Unanswered')?></p><p>Correct answer: <?=e((string)($data['correct_answer']??'Unavailable'))?></p><p>Status: <strong><?= $student===''?'Unanswered':((int)$q['is_correct']===1?'Correct':'Incorrect')?></strong></p>
<?php elseif($q['type']==='match'):$submitted=json_decode($student,true)?:[];?><p>Your answer:</p><ul><?php if($submitted):foreach($submitted as $left=>$right):?><li><?=e((string)$left)?> → <?=e((string)$right)?></li><?php endforeach;else:?><li>Unanswered</li><?php endif;?></ul><p>Correct mapping:</p><ul><?php if(is_array($data['matches']??null)):foreach($data['matches'] as $left=>$right):?><li><?=e((string)$left)?> → <?=e((string)$right)?></li><?php endforeach;else:?><li>Unavailable</li><?php endif;?></ul><p>Status: <strong><?= $student===''||$submitted===[]?'Unanswered':((int)$q['is_correct']===1?'Correct':'Incorrect')?></strong></p>
<?php else:?><p>Your answer:</p><p style="white-space:pre-wrap"><?=e($student!==''?$student:'Unanswered')?></p><p>Reference answer: <?= $q['answer_status']==='available'?e((string)($data['answer']??'Unavailable')):'Unavailable'?></p><p>Status: <strong>Self-graded</strong></p><?php endif;?></div><?php endforeach;?><a class="btn btn-secondary" href="<?=url('student/quiz-builder.php')?>">Create Another Quiz</a></div>
